// static
bool StructTraits<::ash::audio_config::mojom::AudioDevice::DataView, ::ash::audio_config::mojom::AudioDevicePtr>::Read(
    ::ash::audio_config::mojom::AudioDevice::DataView input,
    ::ash::audio_config::mojom::AudioDevicePtr* output) {
  bool success = true;
  ::ash::audio_config::mojom::AudioDevicePtr result(::ash::audio_config::mojom::AudioDevice::New());
  
      if (success)
        result->id = input.id();
      if (success && !input.ReadDisplayName(&result->display_name))
        success = false;
      if (success)
        result->is_active = input.is_active();
      if (success && !input.ReadDeviceType(&result->device_type))
        success = false;
      if (success && !input.ReadNoiseCancellationState(&result->noise_cancellation_state))
        success = false;
      if (success && !input.ReadForceRespectUiGainsState(&result->force_respect_ui_gains_state))
        success = false;
      if (success && !input.ReadHfpMicSrState(&result->hfp_mic_sr_state))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::ash::audio_config::mojom::AudioSystemProperties::DataView, ::ash::audio_config::mojom::AudioSystemPropertiesPtr>::Read(
    ::ash::audio_config::mojom::AudioSystemProperties::DataView input,
    ::ash::audio_config::mojom::AudioSystemPropertiesPtr* output) {
  bool success = true;
  ::ash::audio_config::mojom::AudioSystemPropertiesPtr result(::ash::audio_config::mojom::AudioSystemProperties::New());
  
      if (success && !input.ReadOutputDevices(&result->output_devices))
        success = false;
      if (success)
        result->output_volume_percent = input.output_volume_percent();
      if (success)
        result->input_gain_percent = input.input_gain_percent();
      if (success && !input.ReadOutputMuteState(&result->output_mute_state))
        success = false;
      if (success && !input.ReadInputDevices(&result->input_devices))
        success = false;
      if (success && !input.ReadInputMuteState(&result->input_mute_state))
        success = false;
  *output = std::move(result);
  return success;
}

